/**
 * Pure response/log helpers for the provision-tenant handler, kept out of
 * index.mjs so they can be unit-tested (index.mjs has no harness).
 *
 * The handler is called by the admin portal (create-tenant) and by the
 * self-signup orchestrator (W8), which branches on `errorCode`.
 */

const SENSITIVE_KEY_RE = /licensekey|secret|password|token|api[-_]?key|authorization|cookie/i;

/** Deep-copy `value` with sensitive fields replaced by "(redacted)". Body strings are parsed and redacted too. */
export function redactForLog(value) {
  if (typeof value === "string") {
    const t = value.trim();
    if (t.startsWith("{") || t.startsWith("[")) {
      try { return JSON.stringify(redactForLog(JSON.parse(t))); } catch { /* not JSON */ }
    }
    return value;
  }
  if (Array.isArray(value)) return value.map(redactForLog);
  if (value && typeof value === "object") {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      out[k] = SENSITIVE_KEY_RE.test(k) && v != null && v !== "" ? "(redacted)" : redactForLog(v);
    }
    return out;
  }
  return value;
}

const HEADERS = { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" };
const json = (statusCode, body) => ({ statusCode, headers: HEADERS, body: JSON.stringify(body) });

/** Fields the orchestrator needs on every success shape (design doc 3.1 item 9). */
function tenantSummary({ tenantData, asmData, configUrls, cognitoResources, duration, status, recordKey }) {
  return {
    id: tenantData.tenantId,
    tenantId: tenantData.tenantId,
    // Exact DynamoDB key of the TENANT# record (sk is a creation timestamp).
    recordKey: recordKey ? { id: recordKey.id, sk: recordKey.sk } : undefined,
    tenantName: tenantData.tenantName,
    orgId: tenantData.orgId,
    asmClientId: asmData?.asmClientId,
    serviceProviderId: asmData?.serviceProviderId,
    url: configUrls.tenantUrl,
    userPoolId: cognitoResources.userPoolId,
    spPortalClientId: cognitoResources.spPortalClientId,
    awsConfigUrl: configUrls.awsConfig,
    brandingUrl: configUrls.branding,
    provisioningTime: `${duration}ms`,
    status,
  };
}

/** 200: everything created. */
export function successResponse(ctx, extra = {}) {
  return json(200, {
    success: true,
    message: `Tenant '${ctx.tenantData.tenantId}' provisioned successfully`,
    data: { ...tenantSummary(ctx), ...extra },
  });
}

/** 207: tenant exists, per-tenant tables failed (design doc 3.4 step e). */
export function tablesPendingResponse(ctx, tableError) {
  return json(207, {
    success: false,
    status: "tables_pending",
    message: "Tenant created but table creation failed",
    error: tableError?.message,
    data: tenantSummary({ ...ctx, status: "tables_pending" }),
    recovery: {
      action: "retry_table_creation",
      message: "Invoke this Lambda again with { action: \"retry-tables\", body: { tenantId } }; table creation is idempotent",
      invoke: { action: "retry-tables", body: { tenantId: ctx.tenantData.tenantId } },
    },
  });
}

/**
 * Error messages that may be returned to the caller: only text this Lambda
 * composed itself from validated input. Anything else (upstream replies,
 * SDK errors, unexpected exceptions) is replaced by a generic message; the
 * detail is in the logs, and the caller branches on `errorCode`.
 */
const RETURNABLE_CODES = new Set(["validation_error", "tenant_exists"]);

/**
 * Failure. Carries the stable `errorCode` (and `asmStatus` for ASM
 * failures) so the orchestrator can branch (asm_license_key_used vs
 * asm_forbidden vs tenant_exists vs the rest) without parsing text. No
 * upstream text is ever returned.
 *
 * Status: the error's own statusCode when set (400 validation, 409 tenant
 * exists); 502 for ASM failures (`asm_*`); 500 otherwise.
 */
export function errorResponse(error, { tenantId, duration, rollbackPerformed } = {}) {
  // Never assume a rollback happened: the caller states what it verified
  // (W7 round 19). Anything but an explicit true is false.
  rollbackPerformed = rollbackPerformed === true;
  const code = error?.code || (error?.validationErrors ? "validation_error" : "internal_error");
  const isAsm = code.startsWith("asm_");
  const statusCode = error?.statusCode || (isAsm ? 502 : 500);
  const message =
    RETURNABLE_CODES.has(code) ? error.message
    : isAsm ? `ASM call failed (${error.asmStatus})`
    : "Tenant provisioning failed; see errorCode and server logs";
  return json(statusCode, {
    success: false,
    message: "Tenant provisioning failed",
    errorCode: code,
    error: message,
    ...(isAsm && { asmStatus: error.asmStatus }),
    tenantId,
    provisioningTime: `${duration}ms`,
    rollbackPerformed,
    ...(error?.validationErrors && { validationErrors: error.validationErrors }),
  });
}
